{
  "findings": [
    {
      "check_id": "CKV_AZURE_25",
      "title": "Ensure that 'Threat Detection types' is set to 'All'",
      "resource": "azurerm_mssql_server_security_alert_policy.recovery_db_alerts",
      "severity": "MEDIUM",
      "explanation": "The 'disabled_alerts' list is not empty, which means not all threat detection types are enabled."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_server_security_alert_policy\" \"recovery_db_alerts\" {\n  resource_group_name        = azurerm_resource_group.dr_platform.name\n  server_name                = azurerm_mssql_server.recovery_sql_server.name\n  state                      = \"Enabled\"\n  storage_endpoint           = azurerm_storage_account.backup_storage.primary_blob_endpoint\n  storage_account_access_key = azurerm_storage_account.backup_storage.primary_access_key\n  disabled_alerts = []\n  retention_days = 20\n}",
  "fix_summary": "Removed disabled_alerts to enable all threat detection types."
}
